import type { CSSProperties } from "react";

// Generated by strokit. Colors follow --sk-stroke; prefers-reduced-motion shows the final frame.
const css = `
.sk-xcmybq-0 {
  stroke: var(--sk-stroke, #111111);
  stroke-dasharray: 0.0408 0.0306;
  animation: sk-xcmybq-t0-march calc(800ms / var(--sk-speed, 1)) linear 0ms var(--sk-iterations, infinite) normal both;
  animation-play-state: var(--sk-play-state, running);
}
@keyframes sk-xcmybq-t0-march {
  0% {
    stroke-dashoffset: 0;
  }
  100% {
    stroke-dashoffset: -0.0714;
  }
}
@media (prefers-reduced-motion: reduce) {
  .sk-xcmybq * {
    animation: none;
  }
}
`;

export type SeloMarchProps = {
  /** Width and height (number = px). Defaults to the SVG's own size. */
  size?: number | string;
  /** Playback speed multiplier: 2 plays twice as fast. */
  speed?: number;
  /** true repeats forever, false plays once. Defaults to the exported animation. */
  loop?: boolean;
  paused?: boolean;
  className?: string;
  /** Accessible name. Defaults to "Selo". */
  label?: string;
};

export function SeloMarch({
  size,
  speed = 1,
  loop,
  paused = false,
  className,
  label = "Selo",
}: SeloMarchProps) {
  const style = {
    "--sk-speed": speed,
    "--sk-play-state": paused ? "paused" : "running",
    ...(loop === undefined ? {} : { "--sk-iterations": loop ? "infinite" : 1 }),
  } as CSSProperties;

  return (
    <svg
      viewBox="0 0 140 140"
      width={size ?? 140}
      height={size ?? 140}
      className={className ? `sk-xcmybq ${className}` : "sk-xcmybq"}
      style={style}
      role="img"
      aria-label={label}
    >
      <style>{css}</style>
      <title>{"Selo"}</title>
      <g fill="none" stroke="#111111" strokeLinejoin="round">
        <circle cx="70" cy="70" r="62" strokeWidth="4" pathLength="1" className="sk-xcmybq-0" />
        <circle cx="70" cy="70" r="50" strokeWidth="2" pathLength="1" className="sk-xcmybq-0" />
        <polygon points="70,34 79,58 104,58 84,73 91,98 70,83 49,98 56,73 36,58 61,58" strokeWidth="5" pathLength="1" className="sk-xcmybq-0" />
      </g>
    </svg>
  );
}
